class Solution:
    def isNested(self, string: str) -> bool:
        stack = []
        found_open = False

        for char in string:
            if char == '[':
                if not found_open:
                    stack.append(char)
                else:
                    stack.pop()
                found_open = True
            elif char == ']':
                if not found_open:
                    stack.append(char)
                else:
                    if len(stack) > 1:
                        stack.pop()
                    else:
                        return False

        return len(stack) > 0
