class Solution:
    def doAlgebra(self, operator: List[str], operand: List[int]) -> int:
        res = operand[0]
        for i in range(len(operator)):
            if operator[i] == "+":
                res += operand[i+1]
            elif operator[i] == "-":
                res -= operand[i+1]
            elif operator[i] == "*":
                res *= operand[i+1]
            elif operator[i] == "//":
                res //= operand[i+1]
            else:
                res **= operand[i+1]
